import { fileURLToPath } from 'node:url'
import { logger } from 'storybook/internal/node-logger'
import type { DocgenProviderDescriptor, StoryIndex } from 'storybook/internal/types'
import type { CaliperStorybookOptions } from './index.js'
import { assertValidOptions } from './validate.js'
import { OPTION_KEYS } from './option-keys.js'
import { prefetch } from './prefetch.js'

/**
 * What a preset function receives: Storybook's own options merged with the addon's. Storybook's `cache` is its
 * file-system cache object, not the addon's boolean.
 */
type PresetOptions = Omit<CaliperStorybookOptions, 'cache'> & { cache?: unknown }

/** The part of Storybook's options the prefetch reads: its presets, for the story index. */
interface DevServerOptions extends PresetOptions {
  presets: { apply(extension: 'storyIndexGenerator'): Promise<{ getIndex(): Promise<StoryIndex> } | undefined> }
}

/** The addon's options travel to the docgen worker by structured clone, so only these plain fields go. */
function workerOptions(options: PresetOptions): CaliperStorybookOptions {
  const cache = typeof options.cache === 'boolean' ? options.cache : undefined
  return Object.fromEntries(OPTION_KEYS.map((key) => [key, key === 'cache' ? cache : options[key]]))
}

/** Registered last, the provider wraps React's: it answers first and hands on what it can't document. */
export const experimental_docgenProvider = (
  existing: DocgenProviderDescriptor[] = [],
  options: PresetOptions = {},
): DocgenProviderDescriptor[] => {
  assertValidOptions(options)
  return [
    ...existing,
    { moduleSpecifier: fileURLToPath(new URL('provider.js', import.meta.url)), options: workerOptions(options) },
  ]
}

/** Storybook runs docgen providers only with `features.docgenServer`, which this turns on unless `main.ts` sets it. */
export const isDocgenProviderEnabled = (): boolean => true

const PREFETCH_STORIES = 1

/**
 * When the dev server starts, before a browser has asked, documents the components of the first `prefetchStories`
 * stories through Storybook's docgen service: that starts its worker, the session and the checker, and stores the
 * opening story's answer where the browser reads it. Not awaited, and best effort: a failure costs the first story the
 * time it would have saved.
 */
export const experimental_devServer = <App>(app: App, options: DevServerOptions): App => {
  const count = options.prefetchStories ?? PREFETCH_STORIES
  if (count > 0) void startPrefetch(options, count)
  return app
}

async function startPrefetch(options: DevServerOptions, count: number): Promise<void> {
  try {
    const { getService } = await import('storybook/internal/core-server')
    // Registered by Storybook's own `experimental_devServer`, which runs before an addon's.
    const docgen = getService('core/docgen', { internal: true })
    await prefetch(
      {
        index: async () => {
          const generator = await options.presets.apply('storyIndexGenerator')
          if (!generator) throw new Error('Storybook has no story index')
          return generator.getIndex()
        },
        extract: (id) => docgen.commands.extractDocgen({ id }),
      },
      count,
    )
  } catch (error) {
    logger.debug(`[caliper-docgen] prefetch stopped: ${(error as Error).message}`)
  }
}
export interface CaliperStorybookOptions {
  /** Directories caliper-docgen extracts from, relative to Storybook's working directory. Default: `['src']`. */
  srcDirs?: string[]
  exclude?: string[]
  tsconfigPath?: string
  /** Leave out the HTML attributes a component inherits from its element. Same as `htmlAttributes: 'none'`. */
  skipHtmlProps?: boolean
  /**
   * Which HTML attributes a component inherits from its element to list: `'full'` (all of them, the default),
   * `'curated'` (a compact subset: handlers, `aria-*`, `ref`, common attributes) or `'none'`. Wins over `skipHtmlProps`.
   */
  htmlAttributes?: 'curated' | 'full' | 'none'
  /**
   * Read and write the on-disk caches under `node_modules/.cache`. Default: `true`; `false` reads and writes nothing
   * there and parses everything every run. The output is the same.
   */
  cache?: boolean
  /**
   * Load the type declarations your props reference from installed packages, so props typed by a library resolve
   * instead of degrading. Default: `true`; `false` skips the extra work.
   */
  loadDependencies?: boolean
  /**
   * Which inherited sources of more than 30 props to list as one inherited layer instead of prop by prop. Default:
   * `'none'`, every inherited prop listed.
   */
  collapseInheritedProps?: 'dependencies' | 'all' | 'none'
  /**
   * Resolve a component when a story asks for it instead of every component when Storybook starts. Default: `true`.
   * The props are the same; the session starts sooner and holds only the components your stories use.
   */
  lazy?: boolean
  /**
   * With a lazy session, resolve a few components in the background after it starts. Default: `false`: it did not
   * make the first story faster in measurement.
   */
  warmUp?: boolean
  /**
   * With a lazy session, once this many distinct components have been asked for, resolve all the rest in the
   * background in one parallel pass. It lowers the median story latency of a project read end to end (Spectrum's
   * 50 stories: 19 ms to 5 ms) but not the total time, and raises peak memory by 170 to 420 MB, so it is off by
   * default: `0`.
   */
  fillAfter?: number
  /**
   * When the dev server starts, document the components of this many first stories through Storybook's docgen
   * service, before a browser asks. Default: `1`, the story Storybook opens. `0` waits for the browser.
   */
  prefetchStories?: number
  /**
   * Ask the built-in TypeScript checker for each component a story names. Default: `true`: it is kept warm in the
   * background, asked for exactly the requested component, and the structural props stand when it is slower than
   * `semanticWaitMs`; its answer is kept for the next request. `false` never starts it.
   */
  checker?: boolean
  /** How many milliseconds a story waits for the checker before it takes the structural props. Default: `150`. */
  semanticWaitMs?: number
  /**
   * How many milliseconds a story waits for the checker when caliper-docgen's own pass lists no props for its
   * component (a `ComponentProps<typeof Button>` of a library it cannot read), since there is nothing to show before
   * the checker answers. Default: `2000`. A value below `semanticWaitMs` gives such a story `semanticWaitMs`.
   */
  semanticWaitEmptyMs?: number
  /**
   * When a warning or an error stays on a component's answer, its props may be incomplete. `'degraded'` (the default)
   * hands such a component to the next docgen provider, React's own; `'never'` always answers. Once the checker
   * (`checker`) answers for a component, a warning caliper-docgen's own pass reported about what that answer
   * replaces (a component it could not find, a prop type it could not resolve) is gone from the answer and hands
   * nothing on; one about what the checker could not read either, or the checker's own (it stopped, it is
   * unavailable), stays and does.
   */
  fallback?: 'degraded' | 'never'
}

export { toArgTypes } from './arg-types.js'
export type { ExtractArgTypes } from './arg-types.js'
import type * as Napi from 'caliper-docgen-napi'

export interface SessionOptions {
  /** Absolute source directories. */
  srcDirs: string[]
  exclude?: string[]
  tsconfigPath?: string
  skipHtmlProps?: boolean
  htmlAttributes?: Napi.JsExtractOptions['htmlAttributes']
  /** Read and write the on-disk caches. Default: `true`. */
  cache?: boolean
  loadDependencies?: boolean
  collapseInheritedProps?: Napi.JsExtractOptions['collapseInheritedProps']
  /**
   * Resolve a component when a story asks for it rather than every component at start. Default: `true`. The answers
   * are the same; a session that serves a few components of many starts and holds less.
   */
  lazy?: boolean
  /**
   * After a lazy session starts, resolve a few components in the background so the dependency declarations and memos
   * the stories share are loaded before the first one asks. Default: `false`: measured against the same stories, it
   * did not make the first story faster, because the warm-up and the story compete for the same threads.
   */
  warmUp?: boolean
  /**
   * Once this many distinct components were asked for, resolve the rest in one background pass. Default: `0`, never:
   * it lowers the median story latency but raises peak memory by 170 to 420 MB.
   */
  fillAfter?: number
  /**
   * Ask the built-in TypeScript checker for each component a story names. Default: `true`: it is kept warm, asked for
   * exactly the requested component, and the structural props stand when it is slower than `semanticWaitMs`. `false`
   * never starts it.
   */
  checker?: boolean
  /** How many milliseconds a story waits for the checker before it takes the structural props. Default: `150`. */
  semanticWaitMs?: number
  /**
   * How many milliseconds a story waits for the checker when caliper-docgen's own pass lists no props for its component.
   * Default: `2000`.
   */
  semanticWaitEmptyMs?: number
}

/** What the native session is created with: the session's options, with `lazy` decided by the caller. */
export function toNapiOptions(options: SessionOptions, lazy: boolean): Napi.JsExtractOptions {
  return {
    srcDirs: options.srcDirs,
    exclude: options.exclude,
    tsconfigPath: options.tsconfigPath,
    htmlAttributes: options.htmlAttributes ?? (options.skipHtmlProps ? 'none' : undefined),
    cache: options.cache,
    loadDependencies: options.loadDependencies,
    collapseInheritedProps: options.collapseInheritedProps,
    lazy,
    checker: options.checker,
    semanticWaitMs: options.semanticWaitMs,
    semanticWaitEmptyMs: options.semanticWaitEmptyMs,
  }
}
import { getComponentIdFromEntry, isEligibleStoryEntry } from 'storybook/internal/common'
import type { StoryIndex } from 'storybook/internal/types'

/**
 * The component ids of the first `count` components the stories show, in the index's order: the first is the one
 * Storybook opens when the URL names no story.
 */
export function openingComponents(index: StoryIndex, count: number): string[] {
  const ids: string[] = []
  for (const entry of Object.values(index.entries)) {
    if (ids.length >= count) break
    if (!isEligibleStoryEntry(entry)) continue
    const id = getComponentIdFromEntry(entry)
    if (!ids.includes(id)) ids.push(id)
  }
  return ids
}

/** Where the prefetch reads the stories from and how it asks Storybook's docgen service for one component. */
export interface PrefetchTarget {
  index(): Promise<StoryIndex>
  extract(componentId: string): Promise<unknown>
}

/**
 * Asks the docgen service for the opening components one after another, so each answer is stored where the browser
 * reads it and at most one prefetch request is ahead of a story someone opens. Resolves with the ids it asked for.
 */
export async function prefetch(target: PrefetchTarget, count: number): Promise<string[]> {
  const ids = openingComponents(await target.index(), count)
  // oxlint-disable-next-line no-await-in-loop -- one request at a time, so a story someone opens waits behind one at most
  for (const id of ids) await target.extract(id)
  return ids
}
/**
 * Notices when a lazy session is being read across the whole project. One component resolved alone costs several times
 * what the same component costs in a pass over all of them, so after `after` distinct components the session resolves
 * the rest together, once. `0` never does.
 */
export class Fill {
  private readonly after: number
  private readonly requested = new Set<string>()
  private filling = false

  constructor(after: number) {
    this.after = after
  }

  /** Records that `key` was asked for; true exactly once, when the rest should be resolved now. */
  asked(key: string): boolean {
    this.requested.add(key)
    if (this.filling || this.after <= 0 || this.requested.size < this.after) return false
    this.filling = true
    return true
  }
}
import type { CaliperStorybookOptions } from './index.js'

/**
 * Every key of the addon's options. `satisfies` makes the compiler reject a key that is missing here or that the
 * options type lacks, so the list cannot drift from `CaliperStorybookOptions`. Only `workerOptions` reads it; the
 * session options in `provider.ts` and `options.ts` still name their keys by hand, since they resolve paths and
 * apply defaults.
 */
const OPTION_KEY_SET = {
  srcDirs: true,
  exclude: true,
  tsconfigPath: true,
  skipHtmlProps: true,
  htmlAttributes: true,
  cache: true,
  loadDependencies: true,
  collapseInheritedProps: true,
  lazy: true,
  warmUp: true,
  fillAfter: true,
  prefetchStories: true,
  checker: true,
  semanticWaitMs: true,
  semanticWaitEmptyMs: true,
  fallback: true,
} satisfies Record<keyof CaliperStorybookOptions, true>

export const OPTION_KEYS = Object.keys(OPTION_KEY_SET) as (keyof CaliperStorybookOptions)[]
# caliper-docgen-storybook

A Storybook 11 addon that answers Storybook's docgen requests from a caliper-docgen session, so the props table and controls come from caliper-docgen instead of the TypeScript checker.

```bash
npm install --save-dev caliper-docgen-storybook
```

```ts
// .storybook/main.ts
import type { StorybookConfig } from '@storybook/react-vite'

const config: StorybookConfig = {
  framework: '@storybook/react-vite',
  stories: ['../src/**/*.stories.tsx'],
  addons: [{ name: 'caliper-docgen-storybook', options: { srcDirs: ['src'] } }],
}
export default config
```

The addon registers a docgen provider (`experimental_docgenProvider`) and turns on `features.docgenServer`. For each story file, the provider:

1. Resolves `meta.component` (and `meta.subcomponents`) to a file and export, the way Storybook does.
2. Finds that component in the session. A component imported through a barrel file is matched by its exported name.
3. Converts its react-docgen-typescript-shaped docs to argTypes with `@storybook/react`'s own converter, after the same filtering React's docgen applies.

Before answering, the provider compares every source file's mtime and size with the last look and applies the changed ones, so an answer always includes the edits saved before the request.

## Options

| Option | Default | Meaning |
| --- | --- | --- |
| `srcDirs` | `['src']` | Directories to extract from, relative to Storybook's working directory. |
| `exclude` |  | Glob patterns to skip, gitignore-style and relative to each source directory: `**/*.fixture.tsx`, `legacy/`. A bare name such as `Button` matches only a file or folder named exactly that. |
| `tsconfigPath` |  | tsconfig for path aliases. |
| `skipHtmlProps` | `false` | Leave out the HTML attributes a component inherits from its element. |
| `htmlAttributes` | `full` | `full` lists all of the HTML attributes, `curated` a compact subset (handlers, `aria-*`, `ref`, common attributes), `none` none. Wins over `skipHtmlProps`. |
| `cache` | `true` | Read and write the on-disk caches under `node_modules/.cache`. `false` reads and writes nothing there and parses everything every run; the output is the same. |
| `loadDependencies` | `true` | Read the type declarations your props reference from installed packages, so library-typed props resolve instead of degrading. `false` skips the work. |
| `collapseInheritedProps` | `none` | `none` lists every inherited prop. `dependencies` lists large ambient dependency sources (DOM and ARIA attributes, style systems) as one layer of names; `all` also does so for project sources of more than 30 props. |
