// One cold `storybook dev` run with a browser, timed from the server's spawn.
//   node run.mjs <label> '<addon options json>' [first|deep] [outsideIndex]
// first: open the root URL (Storybook selects the first story), then click through to story `outsideIndex`.
// deep: open story `outsideIndex` directly.
// Prints one JSON row: lead time (spawn -> first browser docgen request), the opening answer, UI time, memory.
import { spawn, execFileSync } from 'node:child_process'
import { existsSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { chromium } from 'playwright'

const [, , label, optionsJson = '{}', mode = 'first', outsideArg = '30'] = process.argv
const APP = '/Users/gabe/Projects/caliper-fixtures/prefetch/app'
const PORT = 6100 + Math.floor(Math.random() * 800)
const LOG = `/Users/gabe/Projects/caliper-fixtures/prefetch/logs/trace-${label}-${Date.now()}.jsonl`
const outsideIndex = Number(outsideArg)

function rows() {
  if (!existsSync(LOG)) return []
  return readFileSync(LOG, 'utf8').trim().split('\n').filter(Boolean).map((line) => JSON.parse(line))
}

function treeRssMb(root) {
  const lines = execFileSync('ps', ['-A', '-o', 'pid=,ppid=,rss='], { encoding: 'utf8' }).trim().split('\n')
  const procs = lines.map((l) => l.trim().split(/\s+/).map(Number))
  const inTree = new Set([root])
  let grew = true
  while (grew) {
    grew = false
    for (const [pid, ppid] of procs) if (inTree.has(ppid) && !inTree.has(pid)) (inTree.add(pid), (grew = true))
  }
  return Math.round(procs.filter(([pid]) => inTree.has(pid)).reduce((sum, [, , rss]) => sum + rss, 0) / 1024)
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms))
const t0 = Date.now()
const sb = spawn(
  process.execPath,
  ['node_modules/storybook/dist/bin/dispatcher.js', 'dev', '-p', String(PORT), '--ci', '--loglevel', process.env.SB_LOGLEVEL ?? 'info'],
  {
    cwd: APP,
    env: { ...process.env, CALIPER_OPTIONS: optionsJson, TRACE_LOG: LOG, STORYBOOK_DISABLE_TELEMETRY: '1' },
    stdio: ['ignore', 'pipe', 'pipe'],
    detached: true,
  },
)
let out = ''
sb.stdout.on('data', (d) => (out += d))
sb.stderr.on('data', (d) => (out += d))
let peak = 0
const sampler = setInterval(() => {
  try {
    peak = Math.max(peak, treeRssMb(sb.pid))
  } catch {
    // ps raced the exit.
  }
}, 100)

const result = { label, mode, options: JSON.parse(optionsJson) }
try {
  // Storybook opens the browser once the index is built and the server listens: the same moment here.
  let index
  for (;;) {
    if (Date.now() - t0 > 120_000 || sb.exitCode !== null) throw new Error(`no index:\n${out}`)
    try {
      const res = await fetch(`http://localhost:${PORT}/index.json`)
      if (res.ok) {
        index = await res.json()
        break
      }
    } catch {
      // Not listening yet.
    }
    await sleep(25)
  }
  result.readyMs = Date.now() - t0
  const stories = Object.values(index.entries).filter((e) => e.type === 'story')
  const first = stories[0]
  const outside = stories[outsideIndex]
  const browser = await chromium.launch()
  const page = await browser.newPage()
  const target = mode === 'deep' ? outside : first
  const url = mode === 'deep' ? `http://localhost:${PORT}/?path=/story/${outside.id}` : `http://localhost:${PORT}/`
  // The manager asks for docgen with a remote `extractDocgen` command over the websocket, and receives the stored
  // payload as a service entry: the browser's own request and answer times.
  const frames = []
  page.on('websocket', (ws) => {
    ws.on('framesent', ({ payload }) => {
      const text = String(payload)
      if (text.includes('extractDocgen')) frames.push({ dir: 'sent', at: Date.now(), text: text.slice(0, 400) })
    })
    ws.on('framereceived', ({ payload }) => {
      const text = String(payload)
      if (text.includes('core/docgen') && text.includes('argTypes'))
        frames.push({ dir: 'recv', at: Date.now(), text: text.slice(0, 400) })
    })
  })
  const wire = (componentId, after) => {
    const ask = frames.find((f) => f.dir === 'sent' && f.at >= after && f.text.includes(`"id":"${componentId}"`))
    const answer =
      ask &&
      frames.find((f) => f.dir === 'recv' && f.at >= ask.at && f.text.includes('command-result') && f.text.includes(`"id":"${componentId}"`))
    const state = frames.find((f) => f.dir === 'recv' && f.at >= after && f.text.includes(`"${componentId}"`))
    return {
      askMs: ask ? ask.at - t0 : null,
      resultAfterAskMs: ask && answer ? answer.at - ask.at : null,
      stateBeforeAskMs: ask && state ? ask.at - state.at : null,
    }
  }
  result.wire = wire
  result.navigateMs = Date.now() - t0
  await page.goto(url)
  // The controls panel lists the component's props once docgen answers: wait for a row of the target's props.
  const answered = async (importPath, after) => {
    for (;;) {
      if (Date.now() - t0 > 180_000) throw new Error(`no answer for ${importPath}`)
      const done = rows().filter((r) => r.importPath === importPath && r.end >= after)
      const browserRow = done.find((r) => r.start >= after)
      if (browserRow) return browserRow
      await sleep(10)
    }
  }
  const firstRow = await answered(target.importPath, t0 + result.navigateMs)
  result.target = target.importPath
  result.firstRequestMs = firstRow.start - t0
  result.leadFromNavigateMs = firstRow.start - t0 - result.navigateMs
  result.firstAnswerMs = firstRow.end - firstRow.start
  result.firstArgTypes = firstRow.argTypes
  result.prefetchRows = rows()
    .filter((r) => r.start < t0 + result.navigateMs)
    .map((r) => ({ importPath: r.importPath, startMs: r.start - t0, durMs: r.end - r.start, argTypes: r.argTypes }))
  // The Controls tab title carries a count badge once the panel has rows.
  await page
    .waitForFunction(() => /Name\tControl\n\S/.test(document.body.innerText), undefined, { timeout: 60_000, polling: 10 })
    .then(() => (result.uiMs = Date.now() - t0))
    .catch(() => (result.uiMs = null))
  if (process.env.DUMP_TEXT) result.text = (await page.evaluate(() => document.body.innerText)).slice(0, 1500)
  await sleep(10_000)
  result.idleRssMb = treeRssMb(sb.pid)
  result.firstWire = wire(target.id.split('--')[0], t0)
  if (mode === 'first' && outside) {
    const before = Date.now()
    await page.goto(`http://localhost:${PORT}/?path=/story/${outside.id}`)
    const row = await answered(outside.importPath, before)
    result.outside = outside.importPath
    result.outsideRequestAfterNavMs = row.start - before
    result.outsideAnswerMs = row.end - row.start
    result.outsideArgTypes = row.argTypes
    await sleep(1000)
    result.outsideWire = wire(outside.id.split('--')[0], before)
  }
  result.peakRssMb = peak
  await browser.close()
} catch (error) {
  result.error = String(error?.message ?? error).slice(0, 2000)
} finally {
  clearInterval(sampler)
  try {
    process.kill(-sb.pid, 'SIGKILL')
  } catch {
    // Already gone.
  }
}
delete result.wire
result.log = LOG
writeFileSync(LOG.replace('.jsonl', '.out.txt'), out)
console.log(JSON.stringify(result))
if (process.env.COLD_VITE) rmSync(`${APP}/node_modules/.cache/storybook`, { recursive: true, force: true })
