// What the dev server (main thread) and the docgen provider (Storybook's docgen worker thread) tell each other. Storybook
// gives a docgen provider no way to reach the browser, and the dev server no way to reach the provider, so the two talk
// over a `BroadcastChannel` of this name: the same process, two threads.

import { BroadcastChannel } from 'node:worker_threads'
import { getComponentIdFromEntry, isEligibleStoryEntry } from 'storybook/internal/common'
import type { IndexEntry, StoryIndex } from 'storybook/internal/types'

const CHANNEL = 'caliper-docgen-storybook'

/** What the dev server tells the provider. */
export type ToProvider =
  /** The browser shows a story of `componentId`: the one component whose answer may be replaced in place. */
  | { type: 'open'; componentId: string }
  /** Resolve these stories' components in the background, in this order, replacing what is still queued. */
  | { type: 'prefetch'; entries: IndexEntry[] }

/** What the provider tells the dev server. */
export type ToDevServer =
  /**
   * The checker has answered every component of `componentId`'s payload, which went out with structural props: asked
   * again, the docgen service stores the checker's answer where the browser reads it.
   */
  { type: 'answered'; componentId: string }

/** One end of the channel. */
export interface Link<Out, In> {
  post(message: Out): void
  listen(receive: (message: In) => void): void
}

/** One end of the named channel, which never keeps its thread alive. */
export function channel<Out, In>(): Link<Out, In> {
  const port = new BroadcastChannel(CHANNEL)
  port.unref()
  return {
    post: (message) => port.postMessage(message),
    listen: (receive) => {
      port.onmessage = (event) => receive((event as MessageEvent<In>).data)
    },
  }
}

/** One story entry per component the stories show, in the index's order (the sidebar's). */
export function componentEntries(index: StoryIndex): IndexEntry[] {
  const seen = new Set<string>()
  const entries: IndexEntry[] = []
  for (const entry of Object.values(index.entries)) {
    if (!isEligibleStoryEntry(entry)) continue
    const id = getComponentIdFromEntry(entry)
    if (seen.has(id)) continue
    seen.add(id)
    entries.push(entry)
  }
  return entries
}

/**
 * The entries of the `count` components after `componentId` in the sidebar, nearest first: the stories someone looking
 * at `componentId` opens next. None when the index does not show `componentId`.
 */
export function neighbours(index: StoryIndex, componentId: string, count: number): IndexEntry[] {
  const entries = componentEntries(index)
  const at = entries.findIndex((entry) => getComponentIdFromEntry(entry) === componentId)
  return at < 0 ? [] : entries.slice(at + 1, at + 1 + count)
}

/** The component a story or docs id belongs to: `button--primary` is `button`'s. */
export function componentOf(storyId: string): string {
  return storyId.split('--')[0]!
}

