// Exploratory: one `storybook dev` run, a browser on a story, every websocket frame that mentions core/docgen logged.
//   node explore.mjs '<addon options json>' [storyIndex]
import { spawn } from 'node:child_process'
import { writeFileSync } from 'node:fs'
import { chromium } from 'playwright'

const [, , optionsJson = '{}', storyArg = '0'] = process.argv
const APP = '/Users/gabe/Projects/caliper-fixtures/storybook-upgrade/app'
const PORT = 6100 + Math.floor(Math.random() * 800)
const OUT = `/Users/gabe/Projects/caliper-fixtures/storybook-upgrade/logs/explore-${Date.now()}`
const sleep = (ms) => new Promise((r) => setTimeout(r, ms))
const t0 = Date.now()
const sb = spawn(process.execPath, ['node_modules/storybook/dist/bin/dispatcher.js', 'dev', '-p', String(PORT), '--ci'], {
  cwd: APP,
  env: { ...process.env, CALIPER_OPTIONS: optionsJson, TRACE_LOG: `${OUT}.trace.jsonl`, STORYBOOK_DISABLE_TELEMETRY: '1' },
  stdio: ['ignore', 'pipe', 'pipe'],
  detached: true,
})
let out = ''
sb.stdout.on('data', (d) => (out += d))
sb.stderr.on('data', (d) => (out += d))
const frames = []
try {
  let index
  for (;;) {
    if (Date.now() - t0 > 120_000) throw new Error(`no index:\n${out}`)
    try {
      const res = await fetch(`http://localhost:${PORT}/index.json`)
      if (res.ok) {
        index = await res.json()
        break
      }
    } catch {}
    await sleep(25)
  }
  const readyMs = Date.now() - t0
  const stories = Object.values(index.entries).filter((e) => e.type === 'story')
  const target = stories[Number(storyArg)]
  const browser = await chromium.launch()
  const page = await browser.newPage()
  page.on('websocket', (ws) => {
    ws.on('framesent', ({ payload }) => frames.push({ dir: 'sent', at: Date.now() - t0, text: String(payload).slice(0, 3000) }))
    ws.on('framereceived', ({ payload }) => frames.push({ dir: 'recv', at: Date.now() - t0, len: String(payload).length, text: String(payload).slice(0, 3000) }))
  })
  let navigations = 0
  page.on('framenavigated', (frame) => frame === page.mainFrame() && navigations++)
  await page.goto(`http://localhost:${PORT}/?path=/story/${target.id}`)
  await sleep(25_000)
  writeFileSync(`${OUT}.frames.json`, JSON.stringify({ readyMs, target, navigations, frames }, null, 1))
  console.log(JSON.stringify({ readyMs, target: target.id, navigations, frames: frames.length, out: OUT }))
  await browser.close()
} finally {
  writeFileSync(`${OUT}.out.txt`, out)
  try {
    process.kill(-sb.pid, 'SIGKILL')
  } catch {}
}

