// One cold `storybook dev` run with a browser on one story, timed from the server's spawn.
//   node upgrade.mjs <app dir> '<addon options json>' <scenario> [story id]
// scenario:
//   open   - open the story directly once the server is ready and stay 30 s
//   away   - open the story, go to another story right after its first answer, come back 20 s later
//   first  - open the root URL (Storybook selects the first story) and stay 15 s
// Prints one JSON row: ready time (spawn -> index.json), the browser's docgen request, every docgen state entry the
// browser received for the story's component (time, argTypes count, fingerprint), whether the page reloaded, peak RSS.
import { spawn, execFileSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import { readFileSync, writeFileSync } from 'node:fs'
import { chromium } from 'playwright'

const [, , app, optionsJson = '{}', scenario = 'open', storyArg = '020a-card--default'] = process.argv
const PORT = 6100 + Math.floor(Math.random() * 800)
const LOGS = '/Users/gabe/Projects/caliper-fixtures/storybook-upgrade/logs'
const sleep = (ms) => new Promise((r) => setTimeout(r, ms))

function treeRssMb(root) {
  const lines = execFileSync('ps', ['-A', '-o', 'pid=,ppid=,rss='], { encoding: 'utf8' }).trim().split('\n')
  const procs = lines.map((l) => l.trim().split(/\s+/).map(Number))
  const inTree = new Set([root])
  let grew = true
  while (grew) {
    grew = false
    for (const [pid, ppid] of procs) if (inTree.has(ppid) && !inTree.has(pid)) (inTree.add(pid), (grew = true))
  }
  return Math.round(procs.filter(([pid]) => inTree.has(pid)).reduce((sum, [, , rss]) => sum + rss, 0) / 1024)
}

const t0 = Date.now()
const sb = spawn(process.execPath, ['node_modules/storybook/dist/bin/dispatcher.js', 'dev', '-p', String(PORT), '--ci'], {
  cwd: app,
  env: { ...process.env, CALIPER_OPTIONS: optionsJson, STORYBOOK_DISABLE_TELEMETRY: '1' },
  stdio: ['ignore', 'pipe', 'pipe'],
  detached: true,
})
let out = ''
sb.stdout.on('data', (d) => (out += d))
sb.stderr.on('data', (d) => (out += d))
let peak = 0
const sampler = setInterval(() => {
  try {
    peak = Math.max(peak, treeRssMb(sb.pid))
  } catch {}
}, 100)

// Clicks the sidebar item of a story id, or of its component when the sidebar shows the component as one item.
const clickStory = (id) => {
  const found = [id, id.split("--")[0]].map((each) => document.querySelector(`[data-item-id="${each}"]`)).find(Boolean)
  const link = found?.matches("a, button") ? found : found?.querySelector("a, button")
  ;(link ?? found)?.click()
  return (link ?? found)?.outerHTML?.slice(0, 120) ?? null
}
const fingerprint = (value) => createHash('sha1').update(JSON.stringify(value ?? null)).digest('hex').slice(0, 10)
const result = { scenario, options: JSON.parse(optionsJson), app }
const asks = []
const entries = []
try {
  let index
  for (;;) {
    if (Date.now() - t0 > 120_000 || sb.exitCode !== null) throw new Error(`no index:\n${out.slice(-3000)}`)
    try {
      const res = await fetch(`http://localhost:${PORT}/index.json`)
      if (res.ok) {
        index = await res.json()
        break
      }
    } catch {}
    await sleep(25)
  }
  result.readyMs = Date.now() - t0
  result.t0 = t0
  const stories = Object.values(index.entries).filter((e) => e.type === 'story')
  const target = scenario === 'first' ? stories[0] : index.entries[storyArg]
  const other = stories.find((s) => s.id.split('--')[0] !== target.id.split('--')[0])
  const cid = target.id.split('--')[0]
  result.story = target.id
  const browser = await chromium.launch()
  const page = await browser.newPage()
  page.on('websocket', (ws) => {
    ws.on('framesent', ({ payload }) => {
      const text = String(payload)
      const shown = text.match(/^\{"type":"(currentStoryWasSet|setCurrentStory)","args":\[\{"storyId":"([^"]+)"/)
      if (shown) asks.push({ at: Date.now() - t0, event: shown[1], storyId: shown[2] })
      if (text.includes('"extractDocgen"') && text.includes('command-invoke')) {
        const id = text.match(/"input":\{"id":"([^"]+)"/)?.[1]
        asks.push({ at: Date.now() - t0, id })
      }
    })
    ws.on('framereceived', ({ payload }) => {
      const text = String(payload)
      if (!text.startsWith('{"type":"services:entry"') || !text.includes('"core/docgen"')) return
      const at = Date.now() - t0
      const message = JSON.parse(text)
      for (const op of message.args[0].patch ?? []) {
        const id = op.path?.split('/')[2]
        entries.push({
          at,
          id,
          op: op.op,
          argTypes: op.value?.argTypes ? Object.keys(op.value.argTypes).length : null,
          fp: fingerprint(op.value?.argTypes),
        })
      }
    })
  })
  let reloads = -1
  page.on('load', () => reloads++)
  result.navigateMs = Date.now() - t0
  const url = scenario === 'first' ? `http://localhost:${PORT}/` : `http://localhost:${PORT}/?path=/story/${target.id}`
  await page.goto(url)
  await page.evaluate(() => (window.__caliperMark = 1))
  const firstEntry = async (id, after) => {
    for (;;) {
      if (Date.now() - t0 > 180_000) throw new Error(`no docgen entry for ${id}`)
      const found = entries.find((e) => e.id === id && e.at >= after)
      if (found) return found
      await sleep(10)
    }
  }
  const first = await firstEntry(cid, 0)
  result.firstEntryMs = first.at
  if (scenario === 'away') {
    // Leave by the sidebar, as a person would: the manager stays loaded.
    const leftAt = Date.now() - t0
    await page.keyboard.press("Alt+ArrowDown")
    result.leftAtMs = leftAt
    result.leftTo = other.id
    await sleep(20_000)
    const backAt = Date.now() - t0
    await page.keyboard.press("Alt+ArrowUp")
    result.backAtMs = backAt
    await sleep(8_000)
  } else if (scenario === 'edit') {
    // Two saved edits of the component, 15 s apart, each read back by Storybook's own refresh of the story.
    const file = `${app}/src/Card.tsx`
    const original = readFileSync(file, 'utf8')
    await sleep(10_000)
    try {
      result.editAtMs = [Date.now() - t0]
      writeFileSync(file, original.replace("tone?: 'neutral' | 'accent'", "tone?: 'neutral' | 'accent' | 'muted'"))
      await sleep(15_000)
      result.editAtMs.push(Date.now() - t0)
      writeFileSync(file, original)
      await sleep(15_000)
    } finally {
      writeFileSync(file, original)
    }
  } else {
    await sleep(scenario === 'first' ? 15_000 : 30_000)
  }
  result.mark = await page.evaluate(() => window.__caliperMark ?? null)
  result.reloads = reloads
  result.panelHasPseudoProp = await page.evaluate(() => document.body.innerText.includes('_hover'))
  result.idleRssMb = treeRssMb(sb.pid)
  result.peakRssMb = peak
  await browser.close()
} catch (error) {
  result.error = String(error?.message ?? error).slice(0, 2000)
} finally {
  clearInterval(sampler)
  try {
    process.kill(-sb.pid, 'SIGKILL')
  } catch {}
}
result.asks = asks
result.entries = entries.filter((e) => e.id === result.story?.split('--')[0] || result.scenario !== 'open')
result.loadavg = execFileSync('sysctl', ['-n', 'vm.loadavg'], { encoding: 'utf8' }).trim()
const file = `${LOGS}/upgrade-${scenario}-${Date.now()}`
writeFileSync(`${file}.out.txt`, out)
console.log(JSON.stringify(result))

