// Summarizes upgrade.mjs rows (one JSON per line on stdin): per browser request of a component, the time to its first
// docgen entry and, when a second fingerprint followed, the time to that upgrade.
import { readFileSync } from 'node:fs'

const median = (xs) => {
  const s = [...xs].sort((a, b) => a - b)
  return s.length ? s[Math.floor((s.length - 1) / 2)] : null
}
for (const line of readFileSync(0, 'utf8').split('\n').filter((l) => l.startsWith('{'))) {
  const r = JSON.parse(line)
  const asks = r.asks.filter((a) => a.id)
  const rows = asks.map((ask) => {
    const next = asks.find((a) => a.at > ask.at && a.id === ask.id)?.at ?? Infinity
    const mine = r.entries.filter((e) => e.id === ask.id && e.at >= ask.at - 2000 && e.at < next)
    const fps = [...new Set(mine.map((e) => e.fp))]
    const first = mine.find((e) => e.at >= ask.at) ?? mine[0]
    const upgrade = mine.find((e) => e.fp !== mine[0]?.fp)
    return {
      id: ask.id,
      firstMs: first ? first.at - ask.at : null,
      upgradeMs: upgrade ? upgrade.at - ask.at : null,
      fps: fps.length,
    }
  })
  console.log(
    JSON.stringify({
      scenario: r.scenario,
      options: r.options,
