import { join } from 'node:path'
import { fileURLToPath } from 'node:url'
import type { IndexEntry } from 'storybook/internal/types'
import { afterAll, beforeAll, describe, expect, it, vi } from 'vitest'
import type { Link, ToDevServer, ToProvider } from '../../src/live.js'
import { createDocgenProvider } from '../../src/provider.js'
import { FakeBinding, entry, rdtDoc } from './fake-binding.js'

const project = fileURLToPath(new URL('../fixtures/project', import.meta.url))
const components = join(project, 'src', 'components')
const cwd = process.cwd()

beforeAll(() => process.chdir(project))
afterAll(() => process.chdir(cwd))

function story(title: string): IndexEntry {
  return {
    type: 'story',
    subtype: 'story',
    id: `${title.toLowerCase()}--basic`,
    name: 'Basic',
    title,
    importPath: `./src/stories/${title}.stories.tsx`,
    tags: [],
  }
}

function binding(): FakeBinding {
  const fake = new FakeBinding({
    components: {
      Button: entry('Button', join(components, 'Button.tsx')),
      Card: entry('Card', join(components, 'Card.tsx')),
      List: entry('List', join(components, 'List.tsx')),
      ListItem: entry('ListItem', join(components, 'List.tsx')),
    },
  })
  fake.docs = {
    Button: rdtDoc('Button', ['label']),
    Card: rdtDoc('Card', ['title']),
    List: rdtDoc('List', ['ordered']),
    ListItem: rdtDoc('ListItem', ['bullet']),
  }
  return fake
}

/** The dev server's end of the channel: what the provider posted, and a way to tell it something. */
function devServer() {
  const posted: ToDevServer[] = []
  let receive: ((message: ToProvider) => void) | undefined
  const link: Link<ToDevServer, ToProvider> = {
    post: (message) => posted.push(message),
    listen: (listener) => {
      receive = listener
    },
  }
  return { link, posted, send: (message: ToProvider) => receive?.(message) }
}

function provider(fake: FakeBinding, link: Link<ToDevServer, ToProvider>) {
  const answer = createDocgenProvider({}, fake, link)(async () => undefined)
  return (title: string) => answer({ entry: story(title) })
}

describe('replacing a structural answer on screen', () => {
  it("tells the dev server once the checker has answered the component on screen, and not again for the checker's answer", async () => {
    const fake = binding()
    fake.awaiting.add('Button')
    const server = devServer()
    const ask = provider(fake, server.link)
    server.send({ type: 'open', componentId: 'button' })

    await ask('Button')
    await vi.waitFor(() => expect(fake.checkerWaits).toEqual([{ keys: ['Button'], waitMs: 60_000 }]))
    expect(server.posted).toEqual([])
    fake.answerChecker('Button')
    await vi.waitFor(() => expect(server.posted).toEqual([{ type: 'answered', componentId: 'button' }]))

    // The dev server asks again, and the checker's answer goes out: nothing is watched.
    await ask('Button')
    await new Promise((resolve) => setTimeout(resolve, 10))
    expect(fake.checkerWaits).toHaveLength(1)
    expect(server.posted).toHaveLength(1)
  })

  it('waits for every component of the payload, its subcomponents included', async () => {
    const fake = binding()
    fake.awaiting.add('List')
    fake.awaiting.add('ListItem')
    const server = devServer()
    const ask = provider(fake, server.link)
    server.send({ type: 'open', componentId: 'list' })
    await ask('List')
    await vi.waitFor(() => expect(fake.checkerWaits.map(({ keys }) => keys)).toEqual([['List', 'ListItem']]))
    fake.answerChecker('List')
    await new Promise((resolve) => setTimeout(resolve, 10))
    expect(server.posted).toEqual([])
    fake.answerChecker('ListItem')
    await vi.waitFor(() => expect(server.posted).toEqual([{ type: 'answered', componentId: 'list' }]))
  })

  it('says nothing for a component the browser does not show, or left before the checker answered', async () => {
    const fake = binding()
    fake.awaiting.add('Button')
    fake.awaiting.add('Card')
    const server = devServer()
    const ask = provider(fake, server.link)

    // Not on screen: a prefetch at start, before a browser opened anything.
    await ask('Card')
    await new Promise((resolve) => setTimeout(resolve, 10))
    expect(fake.checkerWaits).toEqual([])

    server.send({ type: 'open', componentId: 'button' })
    await ask('Button')
    await vi.waitFor(() => expect(fake.checkerWaits).toHaveLength(1))
    server.send({ type: 'open', componentId: 'card' })
    fake.answerChecker('Button')
    await new Promise((resolve) => setTimeout(resolve, 10))
    expect(server.posted).toEqual([])
  })

  it('says nothing when the checker stops without answering', async () => {
    const fake = binding()
    fake.awaiting.add('Button')
    const server = devServer()
    const ask = provider(fake, server.link)
    server.send({ type: 'open', componentId: 'button' })
    await ask('Button')
    await vi.waitFor(() => expect(fake.checkerWaits).toHaveLength(1))
    fake.stopChecker()
    await new Promise((resolve) => setTimeout(resolve, 10))
    expect(server.posted).toEqual([])
  })

  it('replaces a component once per change to the files', async () => {
    const fake = binding()
    fake.awaiting.add('Button')
    const server = devServer()
    const ask = provider(fake, server.link)
    server.send({ type: 'open', componentId: 'button' })
    await ask('Button')
    fake.answerChecker('Button')
    await vi.waitFor(() => expect(server.posted).toHaveLength(1))

    // Structural again with no change to the files: not replaced a second time.
    fake.awaiting.add('Button')
    await ask('Button')
    await new Promise((resolve) => setTimeout(resolve, 10))
    fake.answerChecker('Button')
    await new Promise((resolve) => setTimeout(resolve, 10))
    expect(server.posted).toHaveLength(1)

    // An edit: the checker's earlier answer is gone, and its new one replaces the structural answer once more.
    fake.updates.push({ updatedKeys: ['Button'] })
    fake.awaiting.add('Button')
    await ask('Button')
    await vi.waitFor(() => expect(fake.checkerWaits).toHaveLength(2))
    fake.answerChecker('Button')
    await vi.waitFor(() => expect(server.posted).toHaveLength(2))
  })

  it('watches a component handed on as degraded, which the checker may still answer', async () => {
    const fake = binding()
    fake.awaiting.add('Card')
    fake.output.diagnostics = [{ ...warningOn('Card') }]
    const server = devServer()
    const ask = provider(fake, server.link)
    server.send({ type: 'open', componentId: 'card' })
    expect(await ask('Card')).toBeUndefined()
    await vi.waitFor(() => expect(fake.checkerWaits).toEqual([{ keys: ['Card'], waitMs: 60_000 }]))
  })
})

function warningOn(key: string) {
  return {
    severity: 'warning' as const,
    message: 'Cannot resolve type',
    file: null,
    line: null,
    column: null,
    help: null,
    code: 'x',
    affects: [key],
  }
}

