import { existsSync } from 'node:fs'
import { logger } from 'storybook/internal/node-logger'
import type { IndexEntry, StoryIndex } from 'storybook/internal/types'
import { afterEach, describe, expect, it, vi } from 'vitest'
import type { CaliperStorybookOptions } from '../../src/index.js'
import type { ToDevServer, ToProvider } from '../../src/live.js'
import { experimental_docgenProvider, isDocgenProviderEnabled } from '../../src/preset.js'

/** Storybook's docgen service as the preset finds it: every `getService` call, and the extractions asked of it. */
const core = vi.hoisted(() => ({
  services: [] as string[],
  extracted: [] as string[],
  missing: false,
}))

vi.mock('storybook/internal/core-server', () => ({
  getService: (id: string, options: { internal?: boolean }) => {
    core.services.push(`${id} internal=${String(options.internal)}`)
    if (core.missing) throw new Error(`no service ${id}`)
    return {
      commands: {
        extractDocgen: async (input: { id: string }) => {
          core.extracted.push(input.id)
          return { id: input.id }
        },
      },
    }
  },
}))

/** The provider's end of the channel: what the dev server posted, and a way to answer it. */
const provider = vi.hoisted(() => ({
  posted: [] as unknown[],
  receive: undefined as ((message: unknown) => void) | undefined,
}))

vi.mock('../../src/live.js', async (original) => ({
  ...(await original<typeof import('../../src/live.js')>()),
  channel: () => ({
    post: (message: unknown) => provider.posted.push(message),
    listen: (receive: (message: unknown) => void) => {
      provider.receive = receive
    },
  }),
}))

/** A fresh preset module: the dev server it keeps is one per Storybook process. */
async function preset() {
  vi.resetModules()
  return import('../../src/preset.js')
}

function story(id: string): IndexEntry {
  const title = id.split('--')[0]!
  return { type: 'story', subtype: 'story', id, name: id, title, importPath: `./src/${title}.stories.tsx` }
}

const stories: StoryIndex = {
  v: 5,
  entries: Object.fromEntries(
    ['button--primary', 'button--ghost', 'card--basic', 'menu--basic'].map((id) => [id, story(id)]),
  ),
}

function devServerOptions(extra: CaliperStorybookOptions = {}) {
  const asked: string[] = []
  return {
    asked,
    options: {
      ...extra,
      presets: {
        apply: async (extension: 'storyIndexGenerator') => {
          asked.push(extension)
          return { getIndex: async () => stories }
        },
      },
    },
  }
}

/** Storybook's server channel: the browser's events, by name. */
function serverChannel() {
  const listeners = new Map<string, ((payload?: { storyId?: unknown }) => void)[]>()
  return {
    on: (event: string, listener: (payload?: { storyId?: unknown }) => void) => {
      listeners.set(event, [...(listeners.get(event) ?? []), listener])
    },
    emit: (event: string, payload?: { storyId?: unknown; viewMode?: string }) => {
      for (const listener of listeners.get(event) ?? []) listener(payload)
    },
  }
}

const settle = () => new Promise((resolve) => setTimeout(resolve, 20))

afterEach(() => {
  core.services.length = 0
  core.extracted.length = 0
  core.missing = false
  provider.posted.length = 0
  provider.receive = undefined
  vi.restoreAllMocks()
})

describe('prefetch at dev server start', () => {
  it("documents the opening story's component through Storybook's docgen service by default", async () => {
    const { experimental_devServer } = await preset()
    const app = { name: 'app' }
    const { options, asked } = devServerOptions()
    expect(await experimental_devServer(app, options)).toBe(app)
    await vi.waitFor(() => expect(core.extracted).toEqual(['button']))
    expect(core.services).toEqual(['core/docgen internal=true'])
    expect(asked).toEqual(['storyIndexGenerator'])
    // One story: nothing for the provider to resolve in the background.
    await settle()
    expect(provider.posted).toEqual([])
  })

  it('has the provider resolve the next `prefetchStories - 1` components in the background', async () => {
    const { experimental_devServer } = await preset()
    await experimental_devServer({}, devServerOptions({ prefetchStories: 3 }).options)
    await vi.waitFor(() => expect(provider.posted).toHaveLength(1))
    expect(core.extracted).toEqual(['button'])
    expect(provider.posted).toEqual([{ type: 'prefetch', entries: [story('card--basic'), story('menu--basic')] }])
  })

  it('asks nothing with `prefetchStories: 0`', async () => {
    const { experimental_devServer } = await preset()
    const { options, asked } = devServerOptions({ prefetchStories: 0 })
    await experimental_devServer({}, options)
    await settle()
    expect(core.services).toEqual([])
    expect(asked).toEqual([])
    expect(provider.posted).toEqual([])
  })

  it('logs and returns the app when Storybook has no docgen service', async () => {
    const { experimental_devServer } = await preset()
    core.missing = true
    const debug = vi.spyOn(logger, 'debug').mockImplementation(() => {})
    const app = { name: 'app' }
    expect(await experimental_devServer(app, devServerOptions().options)).toBe(app)
    await vi.waitFor(() =>
      expect(debug).toHaveBeenCalledWith('[caliper-docgen] prefetch stopped: no service core/docgen'),
    )
    expect(core.extracted).toEqual([])
  })
})

describe('following the story the browser shows', () => {
  it('tells the provider the component on screen once per change, and prefetches the components after it', async () => {
    const { experimental_serverChannel } = await preset()
    const channel = serverChannel()
    expect(experimental_serverChannel(channel, devServerOptions({ prefetchStories: 2 }).options)).toBe(channel)
    channel.emit('setCurrentStory', { storyId: 'card--basic' })
    channel.emit('currentStoryWasSet', { storyId: 'card--basic', viewMode: 'story' })
    channel.emit('currentStoryWasSet', {})
    await vi.waitFor(() => expect(provider.posted).toHaveLength(2))
    await settle()
    expect(provider.posted).toEqual([
      { type: 'open', componentId: 'card' },
      { type: 'prefetch', entries: [story('menu--basic')] },
    ])
  })

  it('has the docgen service ask again for the component on screen once the checker answered it, and only for it', async () => {
    const { experimental_serverChannel } = await preset()
    const channel = serverChannel()
    experimental_serverChannel(channel, devServerOptions().options)
    channel.emit('currentStoryWasSet', { storyId: 'button--ghost' })
    provider.receive?.({ type: 'answered', componentId: 'card' } satisfies ToDevServer)
    provider.receive?.({ type: 'answered', componentId: 'button' } satisfies ToDevServer)
    await vi.waitFor(() => expect(core.extracted).toEqual(['button']))
    expect(provider.posted).toEqual([{ type: 'open', componentId: 'button' } satisfies ToProvider])
  })

  it('does not ask again for a component the browser left', async () => {
    const { experimental_serverChannel } = await preset()
    const channel = serverChannel()
    experimental_serverChannel(channel, devServerOptions().options)
    channel.emit('setCurrentStory', { storyId: 'button--ghost' })
    channel.emit('setCurrentStory', { storyId: 'menu--basic' })
    provider.receive?.({ type: 'answered', componentId: 'button' })
    await settle()
    expect(core.extracted).toEqual([])
  })

  it('shares one dev server between the channel and the prefetch', async () => {
    const { experimental_devServer, experimental_serverChannel } = await preset()
    const channel = serverChannel()
    const { options } = devServerOptions({ prefetchStories: 2 })
    experimental_serverChannel(channel, options)
    channel.emit('setCurrentStory', { storyId: 'card--basic' })
    await experimental_devServer({}, options)
    await vi.waitFor(() => expect(core.extracted).toEqual(['button']))
    await settle()
    // The browser already shows a story: the prefetch follows it, not the opening story.
    expect(provider.posted).toEqual([
      { type: 'open', componentId: 'card' },
      { type: 'prefetch', entries: [story('menu--basic')] },
    ])
  })
})

describe('preset', () => {
  it('registers the provider after existing ones, with only cloneable options', async () => {
    const react = { moduleSpecifier: '/react/docgen-worker.js' }
    const options = { srcDirs: ['lib'], fallback: 'never' as const, presets: { apply: () => {} } }
    const [first, ours, ...rest] = await experimental_docgenProvider([react], options)
    expect(first).toBe(react)
    expect(rest).toEqual([])
    expect(ours?.options).toEqual({
      srcDirs: ['lib'],
      exclude: undefined,
      tsconfigPath: undefined,
      skipHtmlProps: undefined,
      htmlAttributes: undefined,
      cache: undefined,
      loadDependencies: undefined,
      collapseInheritedProps: undefined,
      lazy: undefined,
      fillAfter: undefined,
      fallback: 'never',
    })
    expect(ours?.moduleSpecifier).toMatch(/provider\.(js|ts)$/)
    expect(existsSync(ours!.moduleSpecifier.replace(/\.js$/, '.ts')) || existsSync(ours!.moduleSpecifier)).toBe(true)
  })

  it('fails when Storybook starts for an option that is not a choice', () => {
    expect(() => experimental_docgenProvider([], { fallback: 'always' as never })).toThrow(
      "[caliper-docgen] fallback is 'always', expected 'degraded' or 'never'",
    )
  })

  it('forwards every option key to the worker', async () => {
    const options = {
      srcDirs: ['lib'],
      exclude: ['x'],
      tsconfigPath: 'tsconfig.json',
      skipHtmlProps: true,
      htmlAttributes: 'curated',
      cache: false,
      loadDependencies: false,
      collapseInheritedProps: 'all',
      lazy: false,
      fillAfter: 5,
      prefetchStories: 3,
      checker: false,
      semanticWaitMs: 7,
      semanticWaitEmptyMs: 70,
      fallback: 'never',
    } satisfies Record<keyof CaliperStorybookOptions, unknown>
    const [ours] = await experimental_docgenProvider([], options)
    expect(ours?.options).toEqual(options)
  })

  it("leaves out Storybook's own cache, which shares the options object with the addon's", async () => {
    const storybookCache = { get: async () => undefined, set: async () => undefined }
    const [ours] = await experimental_docgenProvider([], { srcDirs: ['lib'], cache: storybookCache })
    expect(ours?.options).toHaveProperty('cache', undefined)
    expect(structuredClone(ours?.options)).toEqual({ srcDirs: ['lib'] })
  })

  it('turns on the docgen server', async () => {
    expect(await isDocgenProviderEnabled()).toBe(true)
  })
})

