    const worker = channel<ToDevServer, ToProvider>()
    const received: ToProvider[] = []
    worker.listen((message) => received.push(message))
    server.post({ type: 'open', componentId: 'button' })
    await vi.waitFor(() => expect(received).toEqual([{ type: 'open', componentId: 'button' }]))
  })

  it("names a story's component", () => {
    expect(componentOf('button--primary')).toBe('button')
    expect(componentOf('intro--docs')).toBe('intro')
